INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Kunden- und Marktperspektive > Berücksichtigung Kunden-Anforderungen-Zufriedenheit
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Kundenanforderungen immer bei der Entwicklung von IT-Lösungen berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Akzeptanz und Nutzen"}, {"text": "Nein", "correct": false, "because": "Kundenfokus ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Kundenzufriedenheit ohne Rückmeldung der Kunden gemessen werden?', 2, '[{"text": "Nein", "correct": true, "because": "Rückmeldung ist Grundlage der Bewertung"}, {"text": "Ja", "correct": false, "because": "Ohne Feedback spekulativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Kundenzufriedenheit unabhängig von der Qualität der IT-Lösung?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität beeinflusst Zufriedenheit"}, {"text": "Ja", "correct": false, "because": "Qualität ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Kundenanforderungen ohne direkte Kommunikation erfasst werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kommunikation ist essenziell für Genauigkeit"}, {"text": "Ja", "correct": false, "because": "Direkter Austausch nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Berücksichtigung von Kundenanforderungen nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Unternehmensgrößen"}, {"text": "Ja", "correct": false, "because": "Universell wichtig"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei der Berücksichtigung von Kundenanforderungen am wichtigsten?', 3, '[{"text": "Kundenkommunikation", "correct": true, "because": "Sichert genaue Erfassung"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Design", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft zur Messung der Kundenzufriedenheit verwendet?', 2, '[{"text": "Umfragen", "correct": true, "because": "Direktes Feedback"}, {"text": "Farbtests", "correct": false, "because": "Ästhetisch"}, {"text": "Kostenanalyse", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Kundenzufriedenheit maßgeblich?', 2, '[{"text": "Produktqualität", "correct": true, "because": "Entscheidend für Nutzererfahrung"}, {"text": "Lieferzeit", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Markenname", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft, Kundenanforderungen genau zu erfassen?', 3, '[{"text": "Interviews", "correct": true, "because": "Direkter Austausch"}, {"text": "Zufallsauswahl", "correct": false, "because": "Unpräzise"}, {"text": "Kostenrechnung", "correct": false, "because": "Wirtschaftlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Kundenzufriedenheit?', 2, '[{"text": "Kundenbindung", "correct": true, "because": "Fördert Loyalität"}, {"text": "Minimale Kosten", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen, Kundenanforderungen zu erfassen?', 4, '[{"text": "Interviews", "correct": true, "because": "Direkter Kontakt"}, {"text": "Umfragen", "correct": true, "because": "Breite Rückmeldung"}, {"text": "Workshops", "correct": true, "because": "Interaktive Diskussion"}, {"text": "Farbtests", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Kundenzufriedenheit?', 3, '[{"text": "Produktqualität", "correct": true, "because": "Kern der Erfahrung"}, {"text": "Support", "correct": true, "because": "Hilft bei Problemen"}, {"text": "Preis-Leistungs-Verhältnis", "correct": true, "because": "Wirtschaftlichkeit"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Berücksichtigung von Kundenanforderungen?', 3, '[{"text": "Kundenzufriedenheit", "correct": true, "because": "Erfüllt Erwartungen"}, {"text": "Wettbewerbsvorteil", "correct": true, "because": "Bessere Anpassung"}, {"text": "Kundenbindung", "correct": true, "because": "Stärkt Beziehung"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei mangelnder Berücksichtigung von Kundenanforderungen auftreten?', 4, '[{"text": "Unzufriedenheit", "correct": true, "because": "Erwartungen nicht erfüllt"}, {"text": "Kundenverlust", "correct": true, "because": "Abwanderung"}, {"text": "Fehlende Akzeptanz", "correct": true, "because": "Produkt wird abgelehnt"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge messen die Kundenzufriedenheit?', 3, '[{"text": "Umfragen", "correct": true, "because": "Direktes Feedback"}, {"text": "Net Promoter Score (NPS)", "correct": true, "because": "Kundenloyalität"}, {"text": "Beschwerdeanalysen", "correct": true, "because": "Identifiziert Probleme"}, {"text": "Farbtests", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Kundenanforderungen fördern die Kundenzufriedenheit. b) Kommunikation mit Kunden ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Anforderungen ja, Kommunikation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Produktqualität beeinflusst die Kundenzufriedenheit. b) Rückmeldungen sind für die Zufriedenheit irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, Rückmeldung wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Umfragen messen die Kundenzufriedenheit effektiv. b) Kundenanforderungen sind nur für große Unternehmen wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Umfragen ja, für alle relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Kundenbindung ist ein Ziel der Zufriedenheit. b) Anforderungen können ohne Kommunikation erfasst werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bindung ja, Kommunikation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Interviews helfen, Kundenanforderungen zu verstehen. b) Zufriedenheit ist unabhängig von der Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Interviews ja, Qualität wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');
